// Mid-line video changes against MAME, every pixel: run.js <profile> --raster.
//
// A family's raster firmware (generated by <family>/gen-raster.js) shows, for each case, a few plain
// lead-in fields and then fields in which a video register is written part-way along many scanlines,
// one CPU cycle later on each line. Both emulators run it:
//   1. in lockstep, instruction by instruction (registers and cycle counts), to HALT, so every write
//      lands on the same cycle in both;
//   2. with MAME recording -aviwrite (one bitmap per emulated frame); for every case a swept field is
//      compared pixel by pixel with ours - the active area and the border - through a colour map
//      learned from the pictures themselves (MAME's palette values are its own).
// A case must also not be vacuous: the swept field must differ from the case's plain lead-in field (or,
// for a case whose writes must not show, equal it).
// Exit code 0 only if the trace is identical, the firmware reaches HALT and every case passes.
const fs = require('fs'), path = require('path');
const { png } = require('./png');
const { loadEmu } = require('./firmware');
const { keepWorkDir } = require('./workdir');
const { lockstep } = require('./lockstep');
const { runMame } = require('./mame');
const { readAvi, toRGBA } = require('./avi');

// t: { label, system, work, args, regs, waitOps, luaPrelude, haltPc, install(), machine(), phaseAddr,
//      fieldAddr, file, cases: [{ name, phase, noEffect }], fields, plain, seconds, geometry }
// geometry (optional, for pictures that are not the MC6847's): { offset(movie) -> { ox, oy } of our frame's
// origin in MAME's bitmap, skipTop: rows at the top left out of the lead-in comparison, origin: [x, y] of
// the active area in our frame, for reporting }
async function runRaster(t, { trace = true, keep = false } = {}) {
  const Emu = loadEmu(), V = Emu.MC6847;
  let W = V.WIDTH, H = V.HEIGHT;
  const CAPTURE = 3;                       // the field shown while the field counter reads 3 (a swept one)
  const PLAIN = t.plain;                   // ... and while it reads t.plain (a lead-in field; see each spec)
  let ok = true;
  t.install();
  if (trace) {
    const code = await lockstep(Object.assign({}, t, { label: `${t.label} ${t.file}`, machine: t.machine() }));
    if (code) ok = false;
  }

  // MAME's frames, logging the phase and field counter at the end of each
  const avi = path.join(t.work, 'raster.avi'), log = path.join(t.work, 'phases.txt');
  for (const f of [avi, log]) try { fs.unlinkSync(f); } catch (e) { /* none */ }
  runMame({
    work: t.work, system: t.system, seconds: t.seconds, args: [...t.args, '-aviwrite', avi],
    lua: `${t.luaPrelude || ''}
local space = manager.machine.devices[":maincpu"].spaces["program"]
local f = io.open("${log}", "wb")
emu.register_frame_done(function()
  f:write(string.format("%d %d\\n", space:read_u8(${t.phaseAddr}), space:read_u8(${t.fieldAddr})))
  f:flush()
end)
`,
  });
  const movie = readAvi(avi);
  const marks = fs.readFileSync(log, 'utf8').trim().split('\n').map((l) => l.split(' ').map(Number));
  const mame = {};
  for (let i = 0; i < Math.min(marks.length, movie.frames.length); i++) {
    const [ph, n] = marks[i];
    if (ph && ph !== 0xFF && !mame[ph] && n === CAPTURE) mame[ph] = toRGBA(movie, movie.frames[i]);
  }
  if (!keep) fs.unlinkSync(avi);

  // ours, by the same rule
  const m = t.machine(), ours = {}, plain = {};
  // (through the bus: on the CoCo 3 the CPU sees its RAM through the GIME; $FF ends the firmware, but RAM
  // may also hold $FF before its first case)
  for (let f = 0, started = false; f < 2000; f++) {
    m.runFrame();
    const ph = m.read(t.phaseAddr), n = m.read(t.fieldAddr);
    if (ph === 0xFF && started) break;
    if (!ph || ph === 0xFF) continue;
    started = true;
    W = m.render().width; H = m.render().height;
    if (!ours[ph] && n === CAPTURE) ours[ph] = Emu.frameToRGBA(m.render()).slice();
    if (!plain[ph] && n === PLAIN) plain[ph] = Emu.frameToRGBA(m.render()).slice();
  }

  // MC6847 pictures: MAME's bitmap has the 256x192 active area with 58 px of border at each side, and 25 rows
  // above it (NTSC) or 50 (PAL, which adds 25 padding lines above the top border). Ours: 32 px and 24 rows.
  const g = t.geometry || {};
  const { ox, oy } = g.offset ? g.offset(movie) : { ox: 58 - V.BORDER_X, oy: (movie.h >= 290 ? 50 : 25) - V.BORDER_Y };
  const [ax, ay] = g.origin || [V.BORDER_X, V.BORDER_Y];
  const rows = Math.min(H, movie.h - oy), cols = Math.min(W, movie.w - ox);
  const M = (cap, x, y) => cap[(y + oy) * movie.w + x + ox] & 0xFFFFFF;
  const O = (fr, x, y) => fr[y * W + x] & 0xFFFFFF;

  // colour map MAME -> ours by majority vote over every compared pixel of every case, one to one
  const votes = new Map();
  for (const c of t.cases) {
    if (!mame[c.phase] || !ours[c.phase]) continue;
    for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {
      const k = M(mame[c.phase], x, y) * 0x1000000 + O(ours[c.phase], x, y);
      votes.set(k, (votes.get(k) || 0) + 1);
    }
  }
  const map = new Map(), used = new Set();
  for (const k of [...votes.keys()].sort((a, b) => votes.get(b) - votes.get(a))) {
    const mc = Math.floor(k / 0x1000000), oc = k % 0x1000000;
    if (!map.has(mc) && !used.has(oc)) { map.set(mc, oc); used.add(oc); }
  }

  let passed = 0;
  fs.mkdirSync(t.work, { recursive: true });
  for (const f of fs.readdirSync(t.work)) if (/^diff-\d+\.png$/.test(f)) fs.unlinkSync(path.join(t.work, f));
  for (const c of t.cases) {
    const mc = mame[c.phase], oc = ours[c.phase], pc = plain[c.phase];
    if (!mc || !oc || !pc) { console.log(`MISSING ${c.name} (MAME ${!!mc}, ours ${!!oc}, plain ${!!pc})`); continue; }
    let diff = 0, first = null;
    const img = Buffer.alloc(W * 3 * rows * 4);
    const put = (x, y, rgb) => { const i = (y * W * 3 + x) * 4; img[i] = rgb & 0xFF; img[i + 1] = (rgb >> 8) & 0xFF; img[i + 2] = (rgb >> 16) & 0xFF; img[i + 3] = 255; };
    for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {
      const mv = M(mc, x, y), ov = O(oc, x, y), same = map.get(mv) === ov;
      if (!same) { diff++; if (!first) first = [x - ax, y - ay]; }
      put(x, y, map.has(mv) ? map.get(mv) : 0xFF00FF); put(W + x, y, ov); put(2 * W + x, y, same ? 0x202020 : 0x0000FF);
    }
    if (diff) fs.writeFileSync(path.join(t.work, `diff-${c.phase}.png`), png(W * 3, rows, img));
    // apart from the first display byte, which the lead-in fields change
    let changed = 0;
    const ignore = g.ignore || ((x, y) => y < V.BORDER_Y + 12);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (!ignore(x, y) && O(oc, x, y) !== O(pc, x, y)) changed++;
    const effectOk = c.noEffect ? changed === 0 : changed > 0;
    if (!diff && effectOk) passed++;
    console.log(`${!diff && effectOk ? 'SAME' : 'DIFF'}  ${String(c.phase).padStart(2)} ${c.name.padEnd(46)} ` +
      (diff ? `${diff} of ${cols * rows} px differ, first at active (${first[0]},${first[1]})` : `0 of ${cols * rows} px differ`) +
      (c.noEffect ? `; ${changed ? `CHANGED ${changed} px from the plain field, which it must not` : 'no change from the plain field, as required'}` :
        `; ${changed} px changed by the writes${effectOk ? '' : ' - nothing changed, so the case proves nothing'}`));
  }
  console.log(`[${t.label}] ${passed}/${t.cases.length} mid-line cases identical with MAME (active area and border)`);
  if (passed !== t.cases.length) ok = false;
  if (keep || !ok) keepWorkDir(t.work, keep ? '--keep' : 'movie and difference images');
  return ok ? 0 : 1;
}

module.exports = { runRaster };
